"""The GraphRAG hasher module."""

import hashlib
from collections.abc import Callable
from typing import Any

import yaml

Hasher = Callable[[str], str]
"""Type alias for a hasher function (data: str) -> str."""


def sha256_hasher(data: str) -> str:
    """Generate a SHA-256 hash for the input data."""
    return hashlib.sha256(data.encode("utf-8")).hexdigest()


def _sort_key(value: Any) -> tuple[tuple[int, str], ...]:
    """Return a tuple for sorting that is total over heterogeneous types."""
    return (type_rank(value), str(value))


def type_rank(value: Any) -> int:
    """Return an ordering rank for the type of value."""
    # This is a rough total order; we only need consistency, not semantic ordering.
    if value is None:
        return 0
    if isinstance(value, bool):
        return 1
    if isinstance(value, (int, float, complex)):
        return 2
    if isinstance(value, str):
        return 3
    if isinstance(value, bytes):
        return 4
    if isinstance(value, (list, tuple)):
        return 5
    if isinstance(value, (set, frozenset)):
        return 6
    if isinstance(value, dict):
        return 7
    return 8


def _is_simple(value: Any, _seen: set[int] | None = None) -> bool:
    """Return True if value contains no objects, cycles, or shared references."""
    if _seen is None:
        _seen = set()
    if value is None or isinstance(value, (bool, int, float, complex, str, bytes)):
        return True
    if isinstance(value, (list, tuple)):
        return all(_is_simple(item, _seen) for item in value)
    if isinstance(value, (set, frozenset)):
        return all(_is_simple(item, _seen) for item in value)
    if isinstance(value, dict):
        # Mixed or non-string keys cannot be sorted by YAML, so they are not simple.
        if not all(isinstance(key, str) for key in value):
            return False
        obj_id = id(value)
        if obj_id in _seen:
            return False  # cycle or alias
        _seen.add(obj_id)
        for key, val in value.items():
            if not _is_simple(key, _seen) or not _is_simple(val, _seen):
                return False
        _seen.remove(obj_id)
        return True
    return False  # custom object


def _canonicalize(value: Any, _seen: dict[int, str] | None = None, _counter: list[int] | None = None) -> Any:
    """Canonicalize value to a YAML-serializable, order-invariant structure.

    - Mappings are sorted by a total order over keys.
    - Custom objects are replaced by their __dict__ (state), recursively.
    - Cycles and shared references are handled by replacing repeated objects with
      a deterministic placeholder based on visitation order.
    """
    if _seen is None:
        _seen = {}
    if _counter is None:
        _counter = [0]

    # Scalars are returned as strings for consistency with previous behavior.
    if value is None or isinstance(value, (bool, int, float, complex, str, bytes)):
        return str(value)

    if isinstance(value, (list, tuple)):
        return tuple(_canonicalize(item, _seen, _counter) for item in value)

    if isinstance(value, (set, frozenset)):
        return tuple(sorted((_canonicalize(item, _seen, _counter) for item in value), key=str))

    if isinstance(value, dict):
        obj_id = id(value)
        if obj_id in _seen:
            # Deterministic placeholder: only depends on the order this dict was first
            # encountered in the traversal, not on its insertion order.
            return ("<seen>", _seen[obj_id])
        # Assign a new placeholder id before recursing into children.
        _counter[0] += 1
        _seen[obj_id] = str(_counter[0])
        result = _canonicalize_items(value, _seen, _counter)
        # Do not remove: aliases and cycles need the mapping to remain available.
        return result

    # Custom object: use its __dict__ if available, otherwise fall back to repr.
    if hasattr(value, "__dict__"):
        return _canonicalize(vars(value), _seen, _counter)

    # Fall back to a string representation; this is not fully canonical but avoids errors.
    return str(value)


def _canonicalize_items(mapping: dict, _seen: dict[int, str], _counter: list[int]) -> tuple[tuple[Any, Any], ...]:
    """Canonicalize a mapping's items, sorted by a total key order.

    The raw items are sorted before canonicalization so that placeholder numbers
    assigned to shared dictionaries do not depend on the original insertion order.
    """
    raw_items = sorted(mapping.items(), key=lambda item: _sort_key(item[0]))
    items = []
    for key, val in raw_items:
        items.append((_canonicalize(key, _seen, _counter), _canonicalize(val, _seen, _counter)))
    return tuple(items)


def make_yaml_serializable(data: Any, _seen: dict[int, str] | None = None) -> Any:
    """Convert data to a YAML-serializable format."""
    return _canonicalize(data, _seen)


def hash_data(data: Any, *, hasher: Hasher | None = None) -> str:
    """Hash the input data dictionary using the specified hasher function.

    Args
    ----
        data: dict[str, Any]
            The input data to be hashed.
            The input data is serialized using yaml
            to support complex data structures such as classes and functions.
        hasher: Hasher | None (default: sha256_hasher)
            The hasher function to use. (data: str) -> str

    Returns
    -------
        str
            The resulting hash of the input data.

    """
    hasher = hasher or sha256_hasher
    if _is_simple(data):
        try:
            return hasher(yaml.dump(data, sort_keys=True))
        except (TypeError, RecursionError):
            pass
    return hasher(yaml.dump(make_yaml_serializable(data), sort_keys=True))
